/**
 * Motifs for catalog modules in R06 Vetenskap (0.28). Same geometry format as motifs.ts.
 * Mathematical signs are drawn as strokes; no letters or digits.
 */
import type { Motif, Part, Role } from './motifs';

const p = (d: string, r: Role, hue?: number): Part => ({ t: 'path', d, r, hue });
const c = (cx: number, cy: number, rad: number, r: Role, hue?: number): Part => ({ t: 'circle', cx, cy, rad, r, hue });
const q = (x: number, y: number, w: number, h: number, r: Role, rx = 1.5, hue?: number): Part => ({ t: 'rect', x, y, w, h, rx, r, hue });
const G = { green: 115, orange: 26, red: 6, yellow: 46, blue: 210, sky: 195, brown: 28, sand: 40, purple: 285, pink: 330, slate: 220 } as const;
const plus = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} H${x + 5 * s} M${x} ${y - 5 * s} V${y + 5 * s}`, 'line');
const minus = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} H${x + 5 * s}`, 'line');
const times = (x: number, y: number, s = 1): Part => p(`M${x - 4 * s} ${y - 4 * s} L${x + 4 * s} ${y + 4 * s} M${x + 4 * s} ${y - 4 * s} L${x - 4 * s} ${y + 4 * s}`, 'line');
const equals = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y - 2.5 * s} H${x + 5 * s} M${x - 5 * s} ${y + 2.5 * s} H${x + 5 * s}`, 'line');
const dots = (pts: number[][], r: number, role: Role = 'main', hue?: number): Part[] => pts.map(([x, y]) => c(x!, y!, r, role, hue));
const axes = (): Part => p('M8 6 V56 H60', 'line');
const grid = (): Part[] => [q(6, 6, 52, 52, 'light', 2), p('M6 19 H58 M6 32 H58 M6 45 H58 M19 6 V58 M32 6 V58 M45 6 V58', 'line')];
const bars = (vals: number[], x = 10, w = 46, base = 54): Part[] => vals.map((v, i) => q(x + i * (w / vals.length) + 1, base - v, w / vals.length - 3, v, i % 2 ? 'accent' : 'main', 1.5));
const star = (x: number, y: number, r: number, role: Role, hue?: number): Part => { const pts = Array.from({ length: 10 }, (_, i) => { const a = -Math.PI / 2 + (i * Math.PI) / 5; const rr = i % 2 ? r * 0.45 : r; return `${(x + Math.cos(a) * rr).toFixed(1)} ${(y + Math.sin(a) * rr).toFixed(1)}`; }); return p(`M${pts.join(' L')} Z`, role, hue); };
const sun = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'main', G.yellow), ...[0, 1, 2, 3, 4, 5, 6, 7].map((i) => { const a = (i / 8) * Math.PI * 2; return p(`M${(x + Math.cos(a) * (r + 3)).toFixed(1)} ${(y + Math.sin(a) * (r + 3)).toFixed(1)} L${(x + Math.cos(a) * (r + 7)).toFixed(1)} ${(y + Math.sin(a) * (r + 7)).toFixed(1)}`, 'line'); })];
const atom = (x: number, y: number, s: number): Part[] => [p(`M${x - 22 * s} ${y} C${x - 22 * s} ${y - 9 * s} ${x + 22 * s} ${y - 9 * s} ${x + 22 * s} ${y} C${x + 22 * s} ${y + 9 * s} ${x - 22 * s} ${y + 9 * s} ${x - 22 * s} ${y} Z`, 'line'), p(`M${x - 11 * s} ${y - 19 * s} C${x - 3 * s} ${y - 23 * s} ${x + 19 * s} ${y + 15 * s} ${x + 11 * s} ${y + 19 * s} C${x + 3 * s} ${y + 23 * s} ${x - 19 * s} ${y - 15 * s} ${x - 11 * s} ${y - 19 * s} Z`, 'line'), p(`M${x + 11 * s} ${y - 19 * s} C${x + 19 * s} ${y - 15 * s} ${x - 3 * s} ${y + 23 * s} ${x - 11 * s} ${y + 19 * s} C${x - 19 * s} ${y + 15 * s} ${x + 3 * s} ${y - 23 * s} ${x + 11 * s} ${y - 19 * s} Z`, 'line'), c(x, y, 5 * s, 'main'), c(x + 22 * s, y, 2.5 * s, 'accent')];
const flask = (x: number, y: number, s: number, hue: number = G.green): Part[] => [p(`M${x - 4 * s} ${y} V${y + 12 * s} L${x - 14 * s} ${y + 30 * s} C${x - 15 * s} ${y + 33 * s} ${x - 13 * s} ${y + 35 * s} ${x - 10 * s} ${y + 35 * s} H${x + 10 * s} C${x + 13 * s} ${y + 35 * s} ${x + 15 * s} ${y + 33 * s} ${x + 14 * s} ${y + 30 * s} L${x + 4 * s} ${y + 12 * s} V${y} Z`, 'light'), p(`M${x - 9 * s} ${y + 21 * s} H${x + 9 * s} L${x + 14 * s} ${y + 30 * s} C${x + 15 * s} ${y + 33 * s} ${x + 13 * s} ${y + 35 * s} ${x + 10 * s} ${y + 35 * s} H${x - 10 * s} C${x - 13 * s} ${y + 35 * s} ${x - 15 * s} ${y + 33 * s} ${x - 14 * s} ${y + 30 * s} Z`, 'main', hue), q(x - 6 * s, y - 2 * s, 12 * s, 3 * s, 'line', 1)];
const tube = (x: number, y: number, h: number, fill: number, hue: number = G.blue): Part[] => [q(x - 4, y, 8, h, 'light', 4), q(x - 4, y + h - fill, 8, fill, 'main', 4, hue), q(x - 5, y - 2, 10, 3, 'line', 1)];
const cell = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'light'), c(x, y, r, 'line'), c(x + r * 0.15, y - r * 0.1, r * 0.35, 'main')];
const dna = (x: number, y1: number, y2: number): Part[] => { const h = y2 - y1; return [p(`M${x - 10} ${y1} C${x + 14} ${y1 + h * 0.25} ${x - 14} ${y1 + h * 0.5} ${x + 10} ${y1 + h * 0.75} C${x + 14} ${y1 + h * 0.85} ${x + 10} ${y2} ${x + 10} ${y2}`, 'line'), p(`M${x + 10} ${y1} C${x - 14} ${y1 + h * 0.25} ${x + 14} ${y1 + h * 0.5} ${x - 10} ${y1 + h * 0.75} C${x - 14} ${y1 + h * 0.85} ${x - 10} ${y2} ${x - 10} ${y2}`, 'line'), ...[0.12, 0.37, 0.62, 0.88].map((t, i) => q(x - 6, y1 + h * t - 1.5, 12, 3, i % 2 ? 'accent' : 'main', 1))]; };
const planet = (x: number, y: number, r: number, hue: number, ring = false): Part[] => [c(x, y, r, 'main', hue), ...(ring ? [p(`M${x - r * 1.7} ${y + r * 0.2} C${x - r * 1.7} ${y - r * 0.5} ${x + r * 1.7} ${y - r * 0.5} ${x + r * 1.7} ${y + r * 0.2}`, 'line')] : [])];
const rocket = (x: number, y: number, s: number): Part[] => [p(`M${x} ${y} C${x + 8 * s} ${y + 8 * s} ${x + 8 * s} ${y + 24 * s} ${x + 6 * s} ${y + 30 * s} H${x - 6 * s} C${x - 8 * s} ${y + 24 * s} ${x - 8 * s} ${y + 8 * s} ${x} ${y} Z`, 'light'), c(x, y + 14 * s, 3 * s, 'main', G.blue), p(`M${x - 6 * s} ${y + 22 * s} L${x - 12 * s} ${y + 32 * s} H${x - 6 * s} Z M${x + 6 * s} ${y + 22 * s} L${x + 12 * s} ${y + 32 * s} H${x + 6 * s} Z`, 'main', G.red), p(`M${x - 4 * s} ${y + 31 * s} L${x} ${y + 42 * s} L${x + 4 * s} ${y + 31 * s} Z`, 'main', G.orange)];
const lens = (x: number, y: number, h: number, r: Role = 'light'): Part => p(`M${x} ${y} C${x + h * 0.25} ${y + h * 0.25} ${x + h * 0.25} ${y + h * 0.75} ${x} ${y + h} C${x - h * 0.25} ${y + h * 0.75} ${x - h * 0.25} ${y + h * 0.25} ${x} ${y} Z`, r);
const sine = (y: number, amp: number, n: number, x1 = 4, x2 = 60): Part => { const w = (x2 - x1) / n; let d = `M${x1} ${y}`; for (let i = 0; i < n; i++) { const xs = x1 + i * w; d += ` C${xs + w * 0.25} ${y - (i % 2 ? -amp : amp) * 1.3} ${xs + w * 0.75} ${y - (i % 2 ? -amp : amp) * 1.3} ${xs + w} ${y}`; } return p(d, 'line'); };
const arrowR = (x1: number, x2: number, y: number): Part => p(`M${x1} ${y} H${x2} M${x2 - 4} ${y - 4} L${x2} ${y} L${x2 - 4} ${y + 4}`, 'line');
const check = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} L${x - 1 * s} ${y + 4 * s} L${x + 6 * s} ${y - 4 * s}`, 'line');
const telescope = (x: number, y: number): Part[] => [p(`M${x} ${y} L${x + 30} ${y - 14} L${x + 34} ${y - 6} L${x + 4} ${y + 8} Z`, 'main'), q(x + 30, y - 16, 6, 12, 'accent', 2), p(`M${x + 14} ${y + 2} L${x + 6} ${y + 26} M${x + 14} ${y + 2} L${x + 22} ${y + 26}`, 'line')];
const doc = (x: number, y: number, w: number, h: number, lines = 3): Part[] => [q(x, y, w, h, 'light', 2), p(Array.from({ length: lines }, (_, i) => `M${x + 5} ${y + 8 + i * 7} H${x + w - (i === lines - 1 ? 12 : 5)}`).join(' '), 'line')];

