function drop0(x: number, y: number, hue: number): Part { return p(`M${x} ${y - 9} C${x - 7} ${y} ${x - 7} ${y + 6} ${x} ${y + 6} C${x + 7} ${y + 6} ${x + 7} ${y} ${x} ${y - 9} Z`, 'main', hue); }
function flowerish(x: number, y: number): Part[] { return [p(`M${x} ${y + 6} V${y + 26}`, 'line'), ...[0, 1, 2, 3, 4].map((i) => { const a = (i / 5) * Math.PI * 2 - Math.PI / 2; return c(x + Math.cos(a) * 6, y + Math.sin(a) * 6, 5, 'main', G.pink); }), c(x, y, 3.5, 'main', G.yellow)]; }

